const AUTH_TRANSACTION_TTL: Duration = Duration::from_secs(10 * 60);
const MAX_CALLER_CREDENTIALS_PER_REQUEST: usize = 8;
const MAX_AVATAR_UPLOAD_BYTES: usize = 20 * 1024 * 1024;
const MAX_PLAYLIST_COVER_UPLOAD_BYTES: usize = 20 * 1024 * 1024;
const MAX_UNI_PLAYLIST_DOCUMENT_BYTES: usize = 16 * 1024 * 1024;
const MAX_UNI_PLAYLIST_IMPORT_ITEMS: usize = 100_000;
const MAX_UNI_PLAYLIST_MATERIALIZE_PAGE_ITEMS: u32 = 500;
const MAX_UNI_PLAYLIST_SOURCE_PAGES: usize = 2_000;
const MAX_CLOUD_PROXY_UPLOAD_BYTES: usize = 500 * 1024 * 1024;
const MAX_PODCAST_EPISODE_UPLOAD_BYTES: usize = 500 * 1024 * 1024;
const MAX_AUDIO_CONTENT_BYTES: usize = 512 * 1024 * 1024;

fn background_task_failure_kind(error: &tokio::task::JoinError) -> &'static str {
    if error.is_panic() {
        "panic"
    } else if error.is_cancelled() {
        "cancelled"
    } else {
        "unknown"
    }
}

async fn await_uni_playlist_task<T>(
    operation: &'static str,
    task: tokio::task::JoinHandle<Result<T, TuneWeaveError>>,
) -> Result<T, TuneWeaveError> {
    match task.await {
        Ok(result) => result,
        Err(error) => {
            tracing::error!(
                event = "background_task_failure",
                task = "uni_playlist_storage",
                operation,
                failure_kind = background_task_failure_kind(&error),
                "TuneWeave background task exited abnormally"
            );
            Err(TuneWeaveError::new(
                ErrorCode::InternalError,
                "Uni Playlist background task failed",
            ))
        }
    }
}

#[derive(Clone, Default)]
struct AuthTransactions {
    entries: Arc<RwLock<HashMap<String, StoredAuthTransaction>>>,
}

#[derive(Clone, Copy, Debug, Default, Eq, PartialEq)]
struct AuthTransactionCounts {
    total: usize,
    qr: usize,
    sms: usize,
}

#[derive(Clone)]
struct StoredAuthTransaction {
    created_at: Instant,
    expires_at: Instant,
    kind: StoredAuthKind,
}

#[derive(Clone)]
enum StoredAuthKind {
    Qr {
        platform: Platform,
        account: String,
        credential_mode: CredentialMode,
        provider_transaction_id: String,
    },
    Challenge {
        platform: Platform,
        credential_mode: CredentialMode,
        request: AuthChallengeRequest,
    },
}

impl StoredAuthKind {
    const fn platform(&self) -> Platform {
        match self {
            Self::Qr { platform, .. } | Self::Challenge { platform, .. } => *platform,
        }
    }

    const fn credential_mode(&self) -> CredentialMode {
        match self {
            Self::Qr {
                credential_mode, ..
            }
            | Self::Challenge {
                credential_mode, ..
            } => *credential_mode,
        }
    }

    const fn method_name(&self) -> &'static str {
        match self {
            Self::Qr { .. } => "qr",
            Self::Challenge {
                request:
                    AuthChallengeRequest {
                        method: ChallengeMethod::Sms,
                        ..
                    },
                ..
            } => "sms",
        }
    }
}

fn credential_mode_name(mode: CredentialMode) -> &'static str {
    match mode {
        CredentialMode::Server => "server",
        CredentialMode::Client => "client",
        CredentialMode::Both => "both",
    }
}

fn auth_state_name(state: AuthState) -> &'static str {
    match state {
        AuthState::Waiting => "waiting",
        AuthState::Scanned => "scanned",
        AuthState::Confirmed => "confirmed",
        AuthState::Expired => "expired",
        AuthState::Failed => "failed",
    }
}

fn auth_transaction_elapsed_ms(transaction: &StoredAuthTransaction) -> u64 {
    u64::try_from(transaction.created_at.elapsed().as_millis()).unwrap_or(u64::MAX)
}

fn log_auth_transaction_started(transaction_id: &str, transaction: &StoredAuthTransaction) {
    tracing::info!(
        event = "auth_transaction",
        phase = "started",
        transaction_id,
        platform = %transaction.kind.platform(),
        auth_method = transaction.kind.method_name(),
        credential_mode = credential_mode_name(transaction.kind.credential_mode()),
        elapsed_ms = auth_transaction_elapsed_ms(transaction),
        "TuneWeave authentication transaction started"
    );
}

fn log_auth_transaction_progress(
    transaction_id: &str,
    transaction: &StoredAuthTransaction,
    state: AuthState,
) {
    tracing::debug!(
        event = "auth_transaction",
        phase = "progress",
        transaction_id,
        platform = %transaction.kind.platform(),
        auth_method = transaction.kind.method_name(),
        credential_mode = credential_mode_name(transaction.kind.credential_mode()),
        auth_state = auth_state_name(state),
        elapsed_ms = auth_transaction_elapsed_ms(transaction),
        "TuneWeave authentication transaction progressed"
    );
}

fn log_auth_transaction_attempt_failure(
    transaction_id: &str,
    transaction: &StoredAuthTransaction,
    error: &TuneWeaveError,
) {
    tracing::debug!(
        event = "auth_transaction",
        phase = "attempt_failed",
        transaction_id,
        platform = %transaction.kind.platform(),
        auth_method = transaction.kind.method_name(),
        credential_mode = credential_mode_name(transaction.kind.credential_mode()),
        error_code = error.code.as_str(),
        retryable = error.retryable,
        elapsed_ms = auth_transaction_elapsed_ms(transaction),
        "TuneWeave authentication transaction attempt failed"
    );
}

fn log_auth_transaction_completed(
    transaction_id: &str,
    transaction: &StoredAuthTransaction,
    state: AuthState,
) {
    let platform = transaction.kind.platform();
    let method = transaction.kind.method_name();
    let credential_mode = credential_mode_name(transaction.kind.credential_mode());
    let state = auth_state_name(state);
    let elapsed_ms = auth_transaction_elapsed_ms(transaction);
    if matches!(state, "expired" | "failed") {
        tracing::warn!(
            event = "auth_transaction",
            phase = "completed",
            transaction_id,
            platform = %platform,
            auth_method = method,
            credential_mode,
            auth_state = state,
            elapsed_ms,
            "TuneWeave authentication transaction completed"
        );
    } else {
        tracing::info!(
            event = "auth_transaction",
            phase = "completed",
            transaction_id,
            platform = %platform,
            auth_method = method,
            credential_mode,
            auth_state = state,
            elapsed_ms,
            "TuneWeave authentication transaction completed"
        );
    }
}

#[derive(Clone, Copy)]
enum AuthOperation {
    PasswordLogin,
    SessionRefresh,
    SessionLogout,
}

impl AuthOperation {
    const fn name(self) -> &'static str {
        match self {
            Self::PasswordLogin => "password_login",
            Self::SessionRefresh => "session_refresh",
            Self::SessionLogout => "session_logout",
        }
    }
}

fn auth_operation_elapsed_ms(started_at: Instant) -> u64 {
    u64::try_from(started_at.elapsed().as_millis()).unwrap_or(u64::MAX)
}

fn log_auth_operation_success(
    operation: AuthOperation,
    platform: Platform,
    credential_mode: CredentialMode,
    started_at: Instant,
    credential_removed: Option<bool>,
    caller_discard_required: Option<bool>,
) {
    tracing::info!(
        event = "auth_operation",
        operation = operation.name(),
        platform = %platform,
        credential_mode = credential_mode_name(credential_mode),
        result = "success",
        elapsed_ms = auth_operation_elapsed_ms(started_at),
        credential_removed_present = credential_removed.is_some(),
        credential_removed = credential_removed.unwrap_or(false),
        caller_discard_required_present = caller_discard_required.is_some(),
        caller_discard_required = caller_discard_required.unwrap_or(false),
        "TuneWeave authentication operation completed"
    );
}

fn log_auth_operation_failure(
    operation: AuthOperation,
    platform: Platform,
    credential_mode: CredentialMode,
    started_at: Instant,
    error: &TuneWeaveError,
) {
    let operation = operation.name();
    let credential_mode = credential_mode_name(credential_mode);
    let error_code = error.code.as_str();
    let elapsed_ms = auth_operation_elapsed_ms(started_at);
    if matches!(
        error.code,
        ErrorCode::UpstreamError
            | ErrorCode::PlatformUnavailable
            | ErrorCode::UpstreamTimeout
            | ErrorCode::InternalError
    ) {
        tracing::error!(
            event = "auth_operation",
            operation,
            platform = %platform,
            credential_mode,
            result = "failure",
            error_code,
            retryable = error.retryable,
            elapsed_ms,
            "TuneWeave authentication operation failed"
        );
    } else {
        tracing::warn!(
            event = "auth_operation",
            operation,
            platform = %platform,
            credential_mode,
            result = "failure",
            error_code,
            retryable = error.retryable,
            elapsed_ms,
            "TuneWeave authentication operation failed"
        );
    }
}

impl AuthTransactions {
    fn take_expired(
        entries: &mut HashMap<String, StoredAuthTransaction>,
        now: Instant,
    ) -> Vec<(String, StoredAuthTransaction)> {
        let expired_ids = entries
            .iter()
            .filter(|(_, transaction)| transaction.expires_at <= now)
            .map(|(transaction_id, _)| transaction_id.clone())
            .collect::<Vec<_>>();
        expired_ids
            .into_iter()
            .filter_map(|transaction_id| {
                entries
                    .remove(&transaction_id)
                    .map(|transaction| (transaction_id, transaction))
            })
            .collect()
    }

    fn log_expired(expired: Vec<(String, StoredAuthTransaction)>) {
        for (transaction_id, transaction) in expired {
            log_auth_transaction_completed(&transaction_id, &transaction, AuthState::Expired);
        }
    }

    fn insert(&self, kind: StoredAuthKind) -> Result<String, TuneWeaveError> {
        let mut entries = self.entries.write().map_err(|_| auth_store_error())?;
        let now = Instant::now();
        let expired = Self::take_expired(&mut entries, now);
        let transaction_id = (0..8)
            .map(|_| {
                let suffix = rand::rng()
                    .sample_iter(Alphanumeric)
                    .take(24)
                    .map(char::from)
                    .collect::<String>();
                format!("tw-auth-{suffix}")
            })
            .find(|transaction_id| !entries.contains_key(transaction_id))
            .ok_or_else(|| {
                TuneWeaveError::new(
                    tuneweave_core::ErrorCode::InternalError,
                    "failed to allocate a unique authentication transaction",
                )
            })?;
        let transaction = StoredAuthTransaction {
            created_at: now,
            expires_at: now + AUTH_TRANSACTION_TTL,
            kind,
        };
        entries.insert(transaction_id.clone(), transaction.clone());
        drop(entries);
        Self::log_expired(expired);
        log_auth_transaction_started(&transaction_id, &transaction);
        Ok(transaction_id)
    }

    fn get(&self, transaction_id: &str) -> Result<StoredAuthTransaction, TuneWeaveError> {
        let mut entries = self.entries.write().map_err(|_| auth_store_error())?;
        let now = Instant::now();
        let expired = Self::take_expired(&mut entries, now);
        let transaction = entries.get(transaction_id).cloned();
        drop(entries);
        Self::log_expired(expired);
        transaction.ok_or_else(|| {
            TuneWeaveError::new(
                tuneweave_core::ErrorCode::ResourceNotFound,
                "authentication transaction was not found or has expired",
            )
        })
    }

    fn remove(
        &self,
        transaction_id: &str,
    ) -> Result<Option<StoredAuthTransaction>, TuneWeaveError> {
        Ok(self
            .entries
            .write()
            .map_err(|_| auth_store_error())?
            .remove(transaction_id))
    }

    fn counts(&self) -> Result<AuthTransactionCounts, TuneWeaveError> {
        let mut entries = self.entries.write().map_err(|_| auth_store_error())?;
        let expired = Self::take_expired(&mut entries, Instant::now());
        let mut counts = AuthTransactionCounts::default();
        for transaction in entries.values() {
            counts.total += 1;
            match transaction.kind {
                StoredAuthKind::Qr { .. } => counts.qr += 1,
                StoredAuthKind::Challenge {
                    request:
                        AuthChallengeRequest {
                            method: ChallengeMethod::Sms,
                            ..
                        },
                    ..
                } => counts.sms += 1,
            }
        }
        drop(entries);
        Self::log_expired(expired);
        Ok(counts)
    }
}

fn auth_store_error() -> TuneWeaveError {
    TuneWeaveError::new(
        tuneweave_core::ErrorCode::InternalError,
        "authentication transaction store lock is poisoned",
    )
}

