#[derive(Clone, Default)]
struct CallerCredentialSet {
    credentials: BTreeMap<Platform, ProviderCredential>,
    providers: BTreeMap<Platform, Arc<dyn MusicProvider>>,
}

#[derive(Clone, Copy)]
enum AccountSelection {
    Optional,
    Default,
}

struct ProviderAccess {
    provider: Arc<dyn MusicProvider>,
    provider_account: Option<String>,
    response_account: Option<String>,
}

impl ProviderAccess {
    fn required_account(&self) -> &str {
        self.provider_account
            .as_deref()
            .expect("default account selection always yields an account")
    }

    fn response<T>(&self, data: T, platform: Platform) -> ApiResponse<T> {
        let mut response = ApiResponse::new(data).with_platform(platform);
        if let Some(account) = &self.response_account {
            response = response.with_account(account.clone());
        }
        response
    }

    fn list_response<T>(&self, data: Vec<T>, platform: Platform) -> ApiResponse<Vec<T>> {
        self.response(data, platform).with_result_count()
    }
}

impl CallerCredentialSet {
    fn parse_headers(
        headers: &HeaderMap,
    ) -> Result<BTreeMap<Platform, ProviderCredential>, TuneWeaveError> {
        let values = headers.get_all(CALLER_CREDENTIAL_HEADER);
        let count = values.iter().count();
        if count > MAX_CALLER_CREDENTIALS_PER_REQUEST {
            return Err(TuneWeaveError::invalid_request(format!(
                "a request accepts at most {MAX_CALLER_CREDENTIALS_PER_REQUEST} caller credentials"
            )));
        }

        let mut credentials = BTreeMap::new();
        for value in values {
            let value = value.to_str().map_err(|_| {
                TuneWeaveError::invalid_request("caller credential header is not valid ASCII")
            })?;
            let credential = CallerCredential::parse(value)?;
            let platform = credential.platform;
            if credentials.insert(platform, credential).is_some() {
                return Err(TuneWeaveError::invalid_request(format!(
                    "only one caller credential is allowed for platform {platform}"
                ))
                .with_platform(platform));
            }
        }
        Ok(credentials)
    }

    fn from_headers(headers: &HeaderMap, state: &AppState) -> Result<Self, TuneWeaveError> {
        let credentials = Self::parse_headers(headers)?;
        let now = unix_time_seconds()?;
        let mut providers = BTreeMap::new();
        for (platform, credential) in &credentials {
            if credential.is_expired_at(now) {
                return Err(TuneWeaveError::new(
                    ErrorCode::AuthenticationRequired,
                    "caller credential has expired",
                )
                .with_platform(*platform));
            }
            let provider = state.registry.require(*platform)?;
            providers.insert(*platform, provider.with_caller_credential(credential)?);
        }
        Ok(Self {
            credentials,
            providers,
        })
    }

    fn select_provider(
        &self,
        state: &AppState,
        platform: Platform,
        explicit_account: Option<&str>,
        account_selection: AccountSelection,
    ) -> Result<ProviderAccess, TuneWeaveError> {
        if self.credentials.contains_key(&platform) {
            if explicit_account.is_some() {
                return Err(TuneWeaveError::invalid_request(
                    "caller credentials cannot be combined with a server account alias",
                )
                .with_platform(platform));
            }
            record_request_provider_access(platform, RequestCredentialSource::Caller);
            return Ok(ProviderAccess {
                provider: self
                    .providers
                    .get(&platform)
                    .cloned()
                    .expect("validated caller credential always has a provider scope"),
                provider_account: Some("default".to_owned()),
                response_account: None,
            });
        }

        let provider = state.registry.require(platform)?;
        let provider_account = match account_selection {
            AccountSelection::Optional => explicit_account
                .map(str::trim)
                .filter(|account| !account.is_empty())
                .map(str::to_owned),
            AccountSelection::Default => Some(account_alias(explicit_account)?),
        };
        record_request_provider_access(
            platform,
            if provider_account.is_some() {
                RequestCredentialSource::Server
            } else {
                RequestCredentialSource::Anonymous
            },
        );
        Ok(ProviderAccess {
            provider,
            response_account: provider_account.clone(),
            provider_account,
        })
    }

    fn single_credential_for(
        &self,
        platform: Platform,
    ) -> Result<Option<&ProviderCredential>, TuneWeaveError> {
        if self.credentials.len() > 1 {
            return Err(TuneWeaveError::invalid_request(
                "this authentication operation accepts at most one caller credential",
            )
            .with_platform(platform));
        }
        if self.credentials.is_empty() {
            return Ok(None);
        }
        self.credentials.get(&platform).map(Some).ok_or_else(|| {
            TuneWeaveError::invalid_request(
                "caller credential platform does not match the authentication platform",
            )
            .with_platform(platform)
        })
    }

    fn scoped_state(&self, state: &AppState) -> Result<AppState, TuneWeaveError> {
        if self.providers.is_empty() {
            return Ok(state.clone());
        }
        let mut registry = ProviderRegistry::new();
        for descriptor in state.registry.descriptors() {
            let provider = if let Some(provider) = self.providers.get(&descriptor.platform) {
                Arc::clone(provider)
            } else {
                state.registry.require(descriptor.platform)?
            };
            registry.register_arc(provider)?;
        }
        Ok(state.with_registry(registry))
    }

    fn apply_stream_accounts(
        &self,
        accounts: &mut BTreeMap<Platform, String>,
    ) -> Result<(), TuneWeaveError> {
        for platform in accounts.keys().copied().collect::<Vec<_>>() {
            record_request_provider_access(platform, RequestCredentialSource::Server);
        }
        for platform in self.credentials.keys() {
            if accounts.contains_key(platform) {
                return Err(TuneWeaveError::invalid_request(
                    "caller credentials cannot be combined with a server account alias",
                )
                .with_platform(*platform));
            }
        }
        accounts.extend(self.credentials.keys().map(|platform| {
            record_request_provider_access(*platform, RequestCredentialSource::Caller);
            (*platform, "default".to_owned())
        }));
        Ok(())
    }
}

impl AppState {
    #[must_use]
    pub fn new(registry: ProviderRegistry, default_platform: Platform) -> Self {
        Self::with_fallbacks(
            registry,
            default_platform,
            vec![
                Platform::Netease,
                Platform::Qq,
                Platform::Kugou,
                Platform::Kuwo,
                Platform::Migu,
            ],
        )
    }

    #[must_use]
    pub fn with_fallbacks(
        registry: ProviderRegistry,
        default_platform: Platform,
        fallback_platforms: Vec<Platform>,
    ) -> Self {
        Self {
            resolver: StreamResolver::new(registry.clone(), fallback_platforms.clone()),
            fallback_platforms,
            auth_transactions: AuthTransactions::default(),
            request_activity: response::RequestActivity::default(),
            uni_playlists: Arc::new(MemoryUniPlaylistStore::default()),
            registry,
            default_platform,
            started_at: Instant::now(),
        }
    }

    #[must_use]
    pub fn with_uni_playlist_store(mut self, store: Arc<dyn UniPlaylistStore>) -> Self {
        self.uni_playlists = store;
        self
    }

    fn with_registry(&self, registry: ProviderRegistry) -> Self {
        Self {
            resolver: StreamResolver::new(registry.clone(), self.fallback_platforms.clone()),
            registry,
            fallback_platforms: self.fallback_platforms.clone(),
            auth_transactions: self.auth_transactions.clone(),
            request_activity: self.request_activity.clone(),
            uni_playlists: Arc::clone(&self.uni_playlists),
            default_platform: self.default_platform,
            started_at: self.started_at,
        }
    }

    pub fn shutdown_snapshot(&self) -> Result<ShutdownSnapshot, TuneWeaveError> {
        let transactions = self.auth_transactions.counts()?;
        Ok(ShutdownSnapshot {
            active_requests: self.request_activity.active(),
            auth_transactions: transactions.total,
            qr_auth_transactions: transactions.qr,
            sms_auth_transactions: transactions.sms,
        })
    }
}

