async fn general_search(
    State(state): State<AppState>,
    headers: HeaderMap,
    params: Result<Query<GeneralSearchParams>, QueryRejection>,
) -> Result<Json<ApiResponse<GeneralSearchResult>>, ApiError> {
    let params = query_params(params)?;
    let query = params
        .q
        .as_deref()
        .map(str::trim)
        .filter(|query| !query.is_empty())
        .ok_or_else(|| TuneWeaveError::invalid_request("q must not be empty"))?;
    let page = parse_u32_parameter("page", params.page.as_deref(), 1)?;
    if page == 0 {
        return Err(TuneWeaveError::invalid_request("page must start at 1").into());
    }
    let limit = parse_u32_parameter("limit", params.limit.as_deref(), 15)?;
    if !(1..=100).contains(&limit) {
        return Err(TuneWeaveError::invalid_request("limit must be between 1 and 100").into());
    }
    let page_start = params
        .page_start
        .as_deref()
        .map(str::trim)
        .map(|value| {
            if value.is_empty() {
                return Err(TuneWeaveError::invalid_request(
                    "page_start must not be empty when provided",
                ));
            }
            serde_json::from_str::<Extensions>(value).map_err(|error| {
                TuneWeaveError::invalid_request(format!(
                    "page_start must be a JSON object: {error}"
                ))
            })
        })
        .transpose()?;
    let platform = search_platform(&state, params.platform.as_deref())?;
    let access = CallerCredentialSet::from_headers(&headers, &state)?.select_provider(
        &state,
        platform,
        params.account.as_deref(),
        AccountSelection::Optional,
    )?;
    let provider = access.provider;
    let account = access.provider_account;
    let result = provider
        .general_search(&GeneralSearchRequest {
            query: query.to_owned(),
            page,
            limit,
            search_id: optional_trimmed(params.search_id),
            page_start,
            highlight: parse_bool_parameter("highlight", params.highlight.as_deref(), true)?,
            account: account.clone(),
        })
        .await?;
    let mut response = ApiResponse::new(result).with_platform(platform);
    if let Some(account) = access.response_account {
        response = response.with_account(account);
    }
    Ok(Json(response))
}

async fn search(
    State(state): State<AppState>,
    headers: HeaderMap,
    params: Result<Query<SearchParams>, QueryRejection>,
) -> Result<Json<ApiResponse<Vec<SearchItem>>>, ApiError> {
    let params = query_params(params)?;
    let query_text = params
        .q
        .as_deref()
        .map(str::trim)
        .filter(|query| !query.is_empty())
        .ok_or_else(|| TuneWeaveError::invalid_request("q must not be empty"))?;
    let kind = parse_search_kind(params.kind.as_deref())?;
    let variant = parse_search_variant(params.variant.as_deref())?;
    let limit = parse_u32_parameter("limit", params.limit.as_deref(), 30)?;
    if !(1..=100).contains(&limit) {
        return Err(TuneWeaveError::invalid_request("limit must be between 1 and 100").into());
    }
    let offset = parse_u32_parameter("offset", params.offset.as_deref(), 0)?;
    let platform = search_platform(&state, params.platform.as_deref())?;
    let credentials = CallerCredentialSet::from_headers(&headers, &state)?;
    let access = credentials.select_provider(
        &state,
        platform,
        params.account.as_deref(),
        AccountSelection::Optional,
    )?;
    let provider = access.provider;
    let account = access.provider_account;
    let search_id = params
        .search_id
        .as_deref()
        .map(str::trim)
        .filter(|search_id| !search_id.is_empty())
        .map(str::to_owned);
    let query = SearchQuery {
        query: query_text.to_owned(),
        kind,
        variant,
        limit,
        offset,
        account: account.clone(),
        search_id,
        highlight: parse_bool_parameter("highlight", params.highlight.as_deref(), false)?,
        selectors: parse_search_selectors(params.selectors.as_deref())?,
        video_filters: parse_video_search_filters(
            kind,
            params.order.as_deref(),
            params.duration.as_deref(),
            params.category_id.as_deref(),
        )?,
    };
    let page = provider.search_catalog(&query).await?;
    let mut response = ApiResponse::new(page.items)
        .with_platform(platform)
        .with_pagination(page.pagination);
    if let Some(account) = access.response_account {
        response = response.with_account(account);
    }

    Ok(Json(response))
}

