#[derive(Clone, Copy, Debug, Default, Eq, PartialEq)]
enum PodcastDetailBackend {
    #[default]
    Default,
    Workbench,
}

#[derive(Debug, Default, Deserialize)]
#[serde(deny_unknown_fields)]
struct PodcastParams {
    account: Option<String>,
    #[serde(alias = "variant", alias = "source")]
    backend: Option<String>,
}

fn parse_podcast_detail_backend(
    value: Option<&str>,
) -> Result<PodcastDetailBackend, TuneWeaveError> {
    match value
        .unwrap_or("default")
        .trim()
        .to_ascii_lowercase()
        .replace('-', "_")
        .as_str()
    {
        "default" | "program" | "dj" => Ok(PodcastDetailBackend::Default),
        "workbench" | "voice" | "creator" => Ok(PodcastDetailBackend::Workbench),
        value => Err(TuneWeaveError::invalid_request(format!(
            "unsupported podcast detail backend: {value}"
        ))
        .with_details(json!({ "allowed": ["default", "workbench"] }))),
    }
}

async fn podcast(
    State(state): State<AppState>,
    Path(reference): Path<String>,
    params: Result<Query<PodcastParams>, QueryRejection>,
    headers: HeaderMap,
) -> Result<Json<ApiResponse<Podcast>>, ApiError> {
    let params = query_params(params)?;
    let reference = parse_reference(reference)?;
    let account = optional_trimmed(params.account);
    let backend = parse_podcast_detail_backend(params.backend.as_deref())?;
    let platform = reference.platform();
    let access = CallerCredentialSet::from_headers(&headers, &state)?.select_provider(
        &state,
        platform,
        account.as_deref(),
        AccountSelection::Optional,
    )?;
    let podcast = match backend {
        PodcastDetailBackend::Default => {
            access
                .provider
                .podcast(reference.id(), access.provider_account.as_deref())
                .await?
        }
        PodcastDetailBackend::Workbench => {
            access
                .provider
                .podcast_workbench(reference.id(), access.provider_account.as_deref())
                .await?
        }
    };
    Ok(Json(access.response(podcast, platform)))
}

#[derive(Debug, Default, Deserialize)]
#[serde(deny_unknown_fields)]
struct PodcastEpisodeListParams {
    account: Option<String>,
    limit: Option<String>,
    offset: Option<String>,
    #[serde(alias = "asc")]
    ascending: Option<String>,
    #[serde(alias = "variant", alias = "source")]
    backend: Option<String>,
}

async fn podcast_episodes(
    State(state): State<AppState>,
    Path(reference): Path<String>,
    params: Result<Query<PodcastEpisodeListParams>, QueryRejection>,
    headers: HeaderMap,
) -> Result<Json<ApiResponse<Vec<PodcastEpisode>>>, ApiError> {
    let params = query_params(params)?;
    let reference = parse_reference(reference)?;
    let backend = parse_podcast_detail_backend(params.backend.as_deref())?;
    let (default_limit, max_limit) = match backend {
        PodcastDetailBackend::Default => (30, 100),
        PodcastDetailBackend::Workbench => (200, 200),
    };
    let limit = parse_u32_parameter("limit", params.limit.as_deref(), default_limit)?;
    if !(1..=max_limit).contains(&limit) {
        return Err(TuneWeaveError::invalid_request(format!(
            "limit must be between 1 and {max_limit}"
        ))
        .into());
    }
    let offset = parse_u32_parameter("offset", params.offset.as_deref(), 0)?;
    let ascending = parse_bool_parameter("ascending", params.ascending.as_deref(), false)?;
    if backend == PodcastDetailBackend::Workbench && ascending {
        return Err(TuneWeaveError::invalid_request(
            "the podcast workbench episode list does not support ascending order",
        )
        .into());
    }
    let account = optional_trimmed(params.account);
    let platform = reference.platform();
    let access = CallerCredentialSet::from_headers(&headers, &state)?.select_provider(
        &state,
        platform,
        account.as_deref(),
        AccountSelection::Optional,
    )?;
    let request = PodcastEpisodeListRequest {
        limit,
        offset,
        ascending,
        account: access.provider_account.clone(),
    };
    let page = match backend {
        PodcastDetailBackend::Default => {
            access
                .provider
                .podcast_episodes(reference.id(), &request)
                .await?
        }
        PodcastDetailBackend::Workbench => {
            access
                .provider
                .podcast_episodes_workbench(reference.id(), &request)
                .await?
        }
    };
    let response = access
        .response(page.items, platform)
        .with_pagination(page.pagination);
    Ok(Json(response))
}

