#[derive(Debug, Default, Deserialize)]
#[serde(deny_unknown_fields)]
struct UniPlaylistItemStreamParams {
    #[serde(alias = "level")]
    quality: Option<String>,
    #[serde(alias = "backend")]
    variant: Option<String>,
    #[serde(alias = "br")]
    bitrate: Option<String>,
    #[serde(alias = "immerseType", alias = "immerse_type")]
    immersive_type: Option<String>,
    playback_platform: Option<String>,
    fallback: Option<String>,
    fallback_platforms: Option<String>,
    unblock: Option<String>,
    source: Option<String>,
    account: Option<String>,
    accounts: Option<String>,
    resolution: Option<String>,
}

#[derive(Clone, Copy, Debug, Default)]
struct StreamControlInput<'a> {
    quality: Option<&'a str>,
    variant: Option<&'a str>,
    bitrate: Option<&'a str>,
    immersive_type: Option<&'a str>,
    playback_platform: Option<&'a str>,
    fallback: Option<&'a str>,
    fallback_platforms: Option<&'a str>,
    unblock: Option<&'a str>,
    source: Option<&'a str>,
    account: Option<&'a str>,
}

#[derive(Clone, Debug)]
struct StreamControls {
    quality: Quality,
    variant: StreamVariant,
    bitrate: Option<u64>,
    immersive_type: Option<ImmersiveAudioType>,
    routing: StreamRouting,
    account: Option<String>,
}

#[derive(Clone, Debug)]
struct ScopedStreamControls {
    controls: StreamControls,
    caller_accounts: BTreeMap<Platform, String>,
}

#[derive(Clone, Debug)]
enum StreamRouting {
    Standard {
        preferred_platform: Option<Platform>,
        fallback: bool,
        fallback_platforms: Vec<Platform>,
    },
    Unblock {
        source: Option<Platform>,
    },
}

impl StreamControls {
    fn resolve_request(&self, origin_platform: Platform) -> ResolveRequest {
        let (playback_platforms, fallback, account_platform) = match &self.routing {
            StreamRouting::Standard {
                preferred_platform,
                fallback,
                fallback_platforms,
            } => {
                let mut platforms = Vec::new();
                if let Some(platform) = preferred_platform {
                    platforms.push(*platform);
                } else if !fallback_platforms.is_empty() {
                    platforms.push(origin_platform);
                }
                platforms.extend(fallback_platforms.iter().copied());
                (
                    platforms,
                    *fallback,
                    preferred_platform.unwrap_or(origin_platform),
                )
            }
            StreamRouting::Unblock { source } => {
                let mut platforms = source.map_or_else(
                    || {
                        vec![
                            Platform::Qq,
                            Platform::Kugou,
                            Platform::Kuwo,
                            Platform::Migu,
                        ]
                    },
                    |source| vec![source],
                );
                platforms.push(origin_platform);
                let account_platform = platforms[0];
                (platforms, true, account_platform)
            }
        };
        let mut request = ResolveRequest {
            quality: self.quality,
            variant: self.variant,
            bitrate: self.bitrate,
            immersive_type: self.immersive_type,
            playback_platforms,
            fallback,
            ..ResolveRequest::default()
        };
        if let Some(account) = self.account.clone() {
            request.accounts.insert(account_platform, account);
        }
        request
    }

    fn resolve_request_with_accounts(
        &self,
        origin_platform: Platform,
        accounts: BTreeMap<Platform, String>,
    ) -> Result<ResolveRequest, TuneWeaveError> {
        let mut request = self.resolve_request(origin_platform);
        for (platform, account) in accounts {
            if request.accounts.insert(platform, account).is_some() {
                return Err(TuneWeaveError::invalid_request(format!(
                    "account and accounts both select an alias for {platform}"
                ))
                .with_details(json!({ "platform": platform })));
            }
        }
        Ok(request)
    }

    fn starts_with_origin(&self, origin_platform: Platform) -> bool {
        match &self.routing {
            StreamRouting::Standard {
                preferred_platform, ..
            } => preferred_platform.is_none_or(|platform| platform == origin_platform),
            StreamRouting::Unblock { source } => source.unwrap_or(Platform::Qq) == origin_platform,
        }
    }

    fn fallback_enabled(&self) -> bool {
        match self.routing {
            StreamRouting::Standard { fallback, .. } => fallback,
            StreamRouting::Unblock { .. } => true,
        }
    }

    fn provider_request(&self, platform: Platform) -> StreamRequest {
        let account_platform = match self.routing {
            StreamRouting::Standard {
                preferred_platform, ..
            } => preferred_platform.unwrap_or(platform),
            StreamRouting::Unblock { source } => source.unwrap_or(Platform::Qq),
        };
        StreamRequest {
            quality: self.quality,
            variant: self.variant,
            bitrate: self.bitrate,
            immersive_type: self.immersive_type,
            account: (account_platform == platform)
                .then(|| self.account.clone())
                .flatten(),
        }
    }
}

impl ScopedStreamControls {
    fn new(
        controls: StreamControls,
        credentials: &CallerCredentialSet,
        origin_platforms: impl IntoIterator<Item = Platform>,
    ) -> Result<Self, TuneWeaveError> {
        for origin_platform in origin_platforms {
            let mut request = controls.resolve_request(origin_platform);
            credentials.apply_stream_accounts(&mut request.accounts)?;
        }
        Ok(Self {
            controls,
            caller_accounts: credentials
                .credentials
                .keys()
                .map(|platform| (*platform, "default".to_owned()))
                .collect(),
        })
    }

    fn resolve_request(&self, origin_platform: Platform) -> ResolveRequest {
        let mut request = self.controls.resolve_request(origin_platform);
        request.accounts.extend(self.caller_accounts.clone());
        request
    }

    fn provider_request(&self, platform: Platform) -> StreamRequest {
        let mut request = self.controls.provider_request(platform);
        if let Some(account) = self.caller_accounts.get(&platform) {
            request.account = Some(account.clone());
        }
        request
    }

    fn starts_with_origin(&self, origin_platform: Platform) -> bool {
        self.controls.starts_with_origin(origin_platform)
    }

    fn fallback_enabled(&self) -> bool {
        self.controls.fallback_enabled()
    }
}

fn parse_stream_accounts(
    value: Option<&str>,
) -> Result<BTreeMap<Platform, String>, TuneWeaveError> {
    let Some(value) = value.map(str::trim).filter(|value| !value.is_empty()) else {
        return Ok(BTreeMap::new());
    };
    let pairs = if value.starts_with('{') {
        serde_json::from_str::<BTreeMap<String, String>>(value).map_err(|_| {
            TuneWeaveError::invalid_request(
                "accounts must be a JSON object or comma-separated platform=alias pairs",
            )
        })?
    } else {
        let mut pairs = BTreeMap::new();
        for entry in value
            .split(',')
            .map(str::trim)
            .filter(|entry| !entry.is_empty())
        {
            let (platform, account) = entry.split_once('=').ok_or_else(|| {
                TuneWeaveError::invalid_request(
                    "accounts must use comma-separated platform=alias pairs",
                )
                .with_details(json!({ "entry": entry }))
            })?;
            let platform = platform.trim().to_owned();
            if pairs.insert(platform.clone(), account.to_owned()).is_some() {
                return Err(TuneWeaveError::invalid_request(format!(
                    "accounts contains duplicate platform {platform}"
                )));
            }
        }
        pairs
    };
    let mut accounts = BTreeMap::new();
    for (platform, account) in pairs {
        let platform = parse_platform_parameter(&platform)?;
        if accounts.insert(platform, account).is_some() {
            return Err(TuneWeaveError::invalid_request(format!(
                "accounts contains duplicate platform {platform}"
            )));
        }
    }
    normalize_stream_accounts(accounts)
}

fn normalize_stream_accounts(
    accounts: BTreeMap<Platform, String>,
) -> Result<BTreeMap<Platform, String>, TuneWeaveError> {
    let mut normalized = BTreeMap::new();
    for (platform, account) in accounts {
        if platform == Platform::Uni {
            return Err(TuneWeaveError::invalid_request(
                "accounts cannot select the local uni platform",
            ));
        }
        let account = account.trim();
        if account.is_empty() || account.len() > 64 {
            return Err(TuneWeaveError::invalid_request(
                "stream account aliases must contain between 1 and 64 bytes",
            )
            .with_details(json!({ "platform": platform })));
        }
        normalized.insert(platform, account.to_owned());
    }
    Ok(normalized)
}

fn parse_stream_controls(input: StreamControlInput<'_>) -> Result<StreamControls, TuneWeaveError> {
    let quality = parse_quality(input.quality)?;
    let variant = parse_stream_variant(input.variant)?;
    let bitrate = parse_optional_u64_parameter("bitrate", input.bitrate)?;
    let immersive_type = parse_immersive_audio_type(input.immersive_type)?;
    let unblock = parse_bool_parameter("unblock", input.unblock, false)?;
    let fallback = parse_bool_parameter("fallback", input.fallback, true)?;
    let routing = if unblock {
        if input.playback_platform.is_some() || input.fallback_platforms.is_some() {
            return Err(TuneWeaveError::invalid_request(
                "unblock cannot be combined with playback_platform or fallback_platforms",
            )
            .with_details(json!({
                "conflicts": ["playback_platform", "fallback_platforms"]
            })));
        }
        StreamRouting::Unblock {
            source: input.source.map(parse_platform_parameter).transpose()?,
        }
    } else {
        StreamRouting::Standard {
            preferred_platform: input
                .playback_platform
                .map(parse_platform_parameter)
                .transpose()?,
            fallback,
            fallback_platforms: parse_platform_list(input.fallback_platforms)?,
        }
    };
    Ok(StreamControls {
        quality,
        variant,
        bitrate,
        immersive_type,
        routing,
        account: input
            .account
            .map(str::trim)
            .filter(|account| !account.is_empty())
            .map(str::to_owned),
    })
}

async fn track_stream(
    State(state): State<AppState>,
    headers: HeaderMap,
    Path(reference): Path<String>,
    params: Result<Query<StreamParams>, QueryRejection>,
) -> Result<Json<ApiResponse<MediaStream>>, ApiError> {
    let params = query_params(params)?;
    let (stream, account) =
        resolve_track_stream_request(&state, &headers, reference, params).await?;
    let resolved_platform = stream.resolved_platform;
    let mut response = ApiResponse::new(stream).with_platform(resolved_platform);
    if let Some(account) = account {
        response = response.with_account(account);
    }

    Ok(Json(response))
}

async fn track_stream_redirect(
    State(state): State<AppState>,
    headers: HeaderMap,
    Path(reference): Path<String>,
    params: Result<Query<StreamParams>, QueryRejection>,
) -> Result<Response, ApiError> {
    let params = query_params(params)?;
    let (stream, _) = resolve_track_stream_request(&state, &headers, reference, params).await?;
    Ok(download_redirect_response(&stream.url))
}

async fn track_stream_content(
    State(state): State<AppState>,
    headers: HeaderMap,
    Path(reference): Path<String>,
    params: Result<Query<DownloadParams>, QueryRejection>,
) -> Result<Response, ApiError> {
    let params = query_params(params)?;
    let reference = parse_reference(reference)?;
    let mut request = download_request(&params)?;
    let access = CallerCredentialSet::from_headers(&headers, &state)?.select_provider(
        &state,
        reference.platform(),
        params.account.as_deref(),
        AccountSelection::Optional,
    )?;
    request.account = access.provider_account;
    let provider = access.provider;
    let track = provider
        .track(reference.id(), request.account.as_deref())
        .await?;
    let content = provider.audio_content(&track, &request).await?;
    audio_content_response(&track, content).map_err(Into::into)
}

fn audio_content_response(
    track: &Track,
    content: AudioContent,
) -> Result<Response, TuneWeaveError> {
    if content.track_ref != track.resource_ref {
        return Err(TuneWeaveError::new(
            ErrorCode::UpstreamError,
            "provider returned audio content for a different track",
        )
        .with_platform(track.platform));
    }
    if content.bytes.is_empty() || content.bytes.len() > MAX_AUDIO_CONTENT_BYTES {
        return Err(TuneWeaveError::new(
            ErrorCode::UpstreamError,
            "provider returned audio content outside the server size bound",
        )
        .with_platform(track.platform));
    }
    if !matches!(
        content.content_type.as_str(),
        "audio/mp4"
            | "audio/mpeg"
            | "audio/flac"
            | "audio/aac"
            | "audio/ogg"
            | "audio/webm"
            | "application/octet-stream"
    ) {
        return Err(TuneWeaveError::new(
            ErrorCode::UpstreamError,
            "provider returned an unsupported audio content type",
        )
        .with_platform(track.platform));
    }
    if content.filename.is_empty()
        || content.filename.len() > 200
        || content.filename.starts_with('.')
        || !content
            .filename
            .bytes()
            .all(|byte| byte.is_ascii_alphanumeric() || matches!(byte, b'-' | b'_' | b'.'))
    {
        return Err(TuneWeaveError::new(
            ErrorCode::UpstreamError,
            "provider returned an unsafe audio filename",
        )
        .with_platform(track.platform));
    }
    let content_length = content.bytes.len().to_string();
    let content_disposition = format!("inline; filename=\"{}\"", content.filename);
    let mut response = Response::new(Body::from(content.bytes));
    response.headers_mut().insert(
        header::CONTENT_TYPE,
        HeaderValue::from_str(&content.content_type).map_err(|_| {
            TuneWeaveError::new(
                ErrorCode::UpstreamError,
                "provider returned an invalid audio content type",
            )
            .with_platform(track.platform)
        })?,
    );
    response.headers_mut().insert(
        header::CONTENT_LENGTH,
        HeaderValue::from_str(&content_length).expect("decimal content length is a valid header"),
    );
    response.headers_mut().insert(
        header::CONTENT_DISPOSITION,
        HeaderValue::from_str(&content_disposition)
            .expect("validated ASCII filename is a valid content disposition"),
    );
    response.headers_mut().insert(
        header::CACHE_CONTROL,
        HeaderValue::from_static("private, no-store"),
    );
    response.headers_mut().insert(
        header::REFERRER_POLICY,
        HeaderValue::from_static("no-referrer"),
    );
    response.headers_mut().insert(
        header::X_CONTENT_TYPE_OPTIONS,
        HeaderValue::from_static("nosniff"),
    );
    Ok(response)
}

async fn resolve_track_stream_request(
    state: &AppState,
    headers: &HeaderMap,
    reference: String,
    params: StreamParams,
) -> Result<(MediaStream, Option<String>), TuneWeaveError> {
    let credentials = CallerCredentialSet::from_headers(headers, state)?;
    let reference = parse_reference(reference)?;
    let controls = parse_stream_controls(StreamControlInput {
        quality: params.quality.as_deref(),
        variant: params.variant.as_deref(),
        bitrate: params.bitrate.as_deref(),
        immersive_type: params.immersive_type.as_deref(),
        playback_platform: params.playback_platform.as_deref(),
        fallback: params.fallback.as_deref(),
        fallback_platforms: params.fallback_platforms.as_deref(),
        unblock: params.unblock.as_deref(),
        source: params.source.as_deref(),
        account: params.account.as_deref(),
    })?;
    let mut request = controls.resolve_request(reference.platform());
    credentials.apply_stream_accounts(&mut request.accounts)?;
    let state = credentials.scoped_state(state)?;

    let origin_provider = state.registry.require(reference.platform())?;
    let origin_account = request.accounts.get(&reference.platform());
    let origin = origin_provider
        .track(reference.id(), origin_account.map(String::as_str))
        .await?;
    let stream = state.resolver.resolve(&origin, &request).await?;
    Ok((stream, controls.account))
}

async fn uni_playlist_item_stream(
    State(state): State<AppState>,
    headers: HeaderMap,
    Path((reference, item_id)): Path<(String, String)>,
    params: Result<Query<UniPlaylistItemStreamParams>, QueryRejection>,
) -> Result<Json<ApiResponse<UniPlaylistItemStream>>, ApiError> {
    let params = query_params(params)?;
    let credentials = CallerCredentialSet::from_headers(&headers, &state)?;
    let (result, legacy_account) =
        resolve_uni_playlist_item_request(&state, &credentials, reference, item_id, params).await?;
    let resolved_platform = result.stream.resolved_platform;
    let mut response = ApiResponse::new(result).with_platform(resolved_platform);
    if let Some(account) = legacy_account {
        response = response.with_account(account);
    }
    Ok(Json(response))
}

async fn uni_playlist_item_stream_redirect(
    State(state): State<AppState>,
    headers: HeaderMap,
    Path((reference, item_id)): Path<(String, String)>,
    params: Result<Query<UniPlaylistItemStreamParams>, QueryRejection>,
) -> Result<Response, ApiError> {
    let params = query_params(params)?;
    let credentials = CallerCredentialSet::from_headers(&headers, &state)?;
    let (result, _) =
        resolve_uni_playlist_item_request(&state, &credentials, reference, item_id, params).await?;
    Ok(download_redirect_response(&result.stream.url))
}

async fn resolve_uni_playlist_item_request(
    state: &AppState,
    credentials: &CallerCredentialSet,
    reference: String,
    item_id: String,
    params: UniPlaylistItemStreamParams,
) -> Result<(UniPlaylistItemStream, Option<String>), TuneWeaveError> {
    let reference = parse_uni_playlist_reference(reference)?;
    let item = state.uni_playlists.item(reference.id(), &item_id)?;
    let accounts = parse_stream_accounts(params.accounts.as_deref())?;
    let (stream, extensions, legacy_account) =
        resolve_uni_playlist_item_playback(state, credentials, &item, &params, accounts).await?;
    Ok((
        UniPlaylistItemStream {
            playlist_ref: reference,
            item_id: item.id,
            source_ref: item.source_ref,
            kind: item.kind,
            stream,
            extensions,
        },
        legacy_account,
    ))
}

async fn resolve_uni_playlist_item_playback(
    state: &AppState,
    credentials: &CallerCredentialSet,
    item: &UniPlaylistItem,
    params: &UniPlaylistItemStreamParams,
    accounts: BTreeMap<Platform, String>,
) -> Result<(MediaStream, Extensions, Option<String>), TuneWeaveError> {
    let controls = parse_stream_controls(StreamControlInput {
        quality: params.quality.as_deref(),
        variant: params.variant.as_deref(),
        bitrate: params.bitrate.as_deref(),
        immersive_type: params.immersive_type.as_deref(),
        playback_platform: params.playback_platform.as_deref(),
        fallback: params.fallback.as_deref(),
        fallback_platforms: params.fallback_platforms.as_deref(),
        unblock: params.unblock.as_deref(),
        source: params.source.as_deref(),
        account: params.account.as_deref(),
    })?;
    let resolution = parse_u32_parameter(
        "resolution",
        params.resolution.as_deref(),
        VideoStreamRequest::DEFAULT_RESOLUTION,
    )?;
    if !(1..=4_320).contains(&resolution) {
        return Err(TuneWeaveError::invalid_request(
            "resolution must be between 1 and 4320",
        ));
    }
    if params.resolution.is_some()
        && !matches!(
            item.kind,
            UniPlaylistItemKind::Mv | UniPlaylistItemKind::Video
        )
    {
        return Err(TuneWeaveError::invalid_request(
            "resolution is only available for MV or video playlist items",
        ));
    }
    let mut request =
        controls.resolve_request_with_accounts(item.source_ref.platform(), accounts)?;
    credentials.apply_stream_accounts(&mut request.accounts)?;
    let state = credentials.scoped_state(state)?;
    let legacy_account = controls.account.clone();
    let stream_extensions = match item.kind {
        UniPlaylistItemKind::Track => {
            let origin = track_from_uni_item(item.clone());
            (
                state.resolver.resolve(&origin, &request).await?,
                Extensions::from([("transport".to_owned(), json!("audio"))]),
            )
        }
        UniPlaylistItemKind::PodcastEpisode => {
            resolve_uni_podcast_episode_stream(&state, item, &request).await?
        }
        UniPlaylistItemKind::Mv | UniPlaylistItemKind::Video => {
            let prefer_native_audio = item.kind == UniPlaylistItemKind::Video
                && item.source_ref.platform() == Platform::Bilibili
                && params.resolution.is_none();
            resolve_uni_video_stream(&state, item, &request, resolution, prefer_native_audio)
                .await?
        }
        UniPlaylistItemKind::RadioStation => {
            resolve_uni_radio_stream(&state, item, &request).await?
        }
    };
    let (stream, mut extensions) = stream_extensions;
    extensions.insert("strict_match".to_owned(), json!(request.strict_match));
    extensions.insert(
        "account_platforms".to_owned(),
        json!(request.accounts.keys().copied().collect::<Vec<_>>()),
    );
    Ok((stream, extensions, legacy_account))
}

async fn resolve_uni_podcast_episode_stream(
    state: &AppState,
    item: &UniPlaylistItem,
    request: &ResolveRequest,
) -> Result<(MediaStream, Extensions), TuneWeaveError> {
    let origin_platform = item.source_ref.platform();
    let account = request.accounts.get(&origin_platform).map(String::as_str);
    let provider = state.registry.require(origin_platform)?;
    let episode = provider
        .podcast_episode(item.source_ref.id(), account)
        .await?;
    let audio = episode.audio.as_ref().ok_or_else(|| {
        TuneWeaveError::new(
            ErrorCode::UpstreamError,
            "podcast episode did not expose a playable audio resource",
        )
        .with_platform(origin_platform)
        .with_details(json!({ "episode_ref": episode.resource_ref }))
    })?;
    let stream = state.resolver.resolve(audio, request).await?;
    Ok((
        stream,
        Extensions::from([
            ("transport".to_owned(), json!("podcast_audio")),
            ("episode".to_owned(), json!(episode)),
        ]),
    ))
}

async fn resolve_uni_video_stream(
    state: &AppState,
    item: &UniPlaylistItem,
    request: &ResolveRequest,
    resolution: u32,
    prefer_native_audio: bool,
) -> Result<(MediaStream, Extensions), TuneWeaveError> {
    let origin_platform = item.source_ref.platform();
    let origin = track_from_uni_item(item.clone());
    let platforms = state.resolver.platform_sequence(origin_platform, request);
    let mut attempts = Vec::new();
    let mut last_error = None;
    for platform in platforms {
        if platform == origin_platform {
            let account = request.accounts.get(&platform).cloned();
            let provider = match state.registry.require(platform) {
                Ok(provider) => provider,
                Err(error) => {
                    attempts.push(stream_failed_attempt(
                        platform,
                        account,
                        Some(item.source_ref.clone()),
                        Some(1.0),
                        &error,
                    ));
                    last_error = Some(error);
                    continue;
                }
            };
            let kind = match item.kind {
                UniPlaylistItemKind::Mv => VideoResourceKind::Mv,
                UniPlaylistItemKind::Video => VideoResourceKind::Video,
                _ => unreachable!("video resolver only accepts MV or video items"),
            };
            if prefer_native_audio {
                if !provider.supports(Capability::VideoAudioStream) {
                    let error = TuneWeaveError::unsupported(platform, Capability::VideoAudioStream);
                    attempts.push(stream_failed_attempt(
                        platform,
                        account,
                        Some(item.source_ref.clone()),
                        Some(1.0),
                        &error,
                    ));
                    last_error = Some(error);
                    continue;
                }
                let mut audio_request = VideoAudioStreamRequest::new(kind, request.quality);
                audio_request.account.clone_from(&account);
                match provider
                    .video_audio_stream(item.source_ref.id(), &audio_request)
                    .await
                {
                    Ok(audio) if audio.available && audio.url.is_some() => {
                        let mut stream = media_stream_from_video_audio(
                            &item.source_ref,
                            audio.clone(),
                            account,
                        )?;
                        attempts.append(&mut stream.attempts);
                        stream.attempts = attempts;
                        return Ok((
                            stream,
                            Extensions::from([
                                ("transport".to_owned(), json!("native_video_audio")),
                                ("native_video_audio_stream".to_owned(), json!(audio)),
                                ("video_audio_fallback".to_owned(), json!(false)),
                            ]),
                        ));
                    }
                    Ok(audio) => {
                        let error = TuneWeaveError::new(
                            ErrorCode::ResourceNotFound,
                            "video item did not expose a playable audio stream URL",
                        )
                        .with_platform(platform)
                        .with_details(json!({
                            "video_ref": audio.video_ref,
                            "part_ref": audio.part_ref,
                            "requested_quality": audio.requested_quality,
                            "actual_quality": audio.actual_quality,
                            "tier": audio.tier,
                            "platform_quality_id": audio.platform_quality_id,
                            "downgraded": audio.downgraded,
                            "message": audio.message
                        }));
                        attempts.push(stream_failed_attempt(
                            platform,
                            account,
                            Some(item.source_ref.clone()),
                            Some(1.0),
                            &error,
                        ));
                        last_error = Some(error);
                    }
                    Err(error) => {
                        attempts.push(stream_failed_attempt(
                            platform,
                            account,
                            Some(item.source_ref.clone()),
                            Some(1.0),
                            &error,
                        ));
                        last_error = Some(error);
                    }
                }
                continue;
            }
            let mut video_request = VideoStreamRequest::new(kind, resolution);
            video_request.account.clone_from(&account);
            match provider
                .video_stream(item.source_ref.id(), &video_request)
                .await
            {
                Ok(video) if video.available && video.url.is_some() => {
                    let mut stream = media_stream_from_video(
                        &item.source_ref,
                        video.clone(),
                        request.quality,
                        account,
                    )?;
                    attempts.append(&mut stream.attempts);
                    stream.attempts = attempts;
                    return Ok((
                        stream,
                        Extensions::from([
                            ("transport".to_owned(), json!("native_video")),
                            ("native_video_stream".to_owned(), json!(video)),
                        ]),
                    ));
                }
                Ok(video) => {
                    let error = TuneWeaveError::new(
                        ErrorCode::ResourceNotFound,
                        "video item did not expose a playable stream URL",
                    )
                    .with_platform(platform)
                    .with_details(json!({ "video_stream": video }));
                    attempts.push(stream_failed_attempt(
                        platform,
                        account,
                        Some(item.source_ref.clone()),
                        Some(1.0),
                        &error,
                    ));
                    last_error = Some(error);
                }
                Err(error) => {
                    attempts.push(stream_failed_attempt(
                        platform,
                        account,
                        Some(item.source_ref.clone()),
                        Some(1.0),
                        &error,
                    ));
                    last_error = Some(error);
                }
            }
        } else {
            match state
                .resolver
                .resolve_on_platforms(&origin, request, &[platform])
                .await
            {
                Ok(mut stream) => {
                    attempts.append(&mut stream.attempts);
                    stream.attempts = attempts;
                    return Ok((
                        stream,
                        Extensions::from([
                            ("transport".to_owned(), json!("matched_audio")),
                            ("video_audio_fallback".to_owned(), json!(true)),
                        ]),
                    ));
                }
                Err(error) => {
                    let mut failed = stream_error_attempts(&error).unwrap_or_else(|| {
                        vec![stream_failed_attempt(
                            platform,
                            request.accounts.get(&platform).cloned(),
                            None,
                            None,
                            &error,
                        )]
                    });
                    attempts.append(&mut failed);
                    last_error = Some(error);
                }
            }
        }
    }
    Err(stream_resolution_error(
        item,
        attempts,
        last_error,
        "video playlist item could not be played",
    ))
}

async fn resolve_uni_radio_stream(
    state: &AppState,
    item: &UniPlaylistItem,
    request: &ResolveRequest,
) -> Result<(MediaStream, Extensions), TuneWeaveError> {
    let origin_platform = item.source_ref.platform();
    let platforms = state.resolver.platform_sequence(origin_platform, request);
    let mut attempts = Vec::new();
    let mut last_error = None;
    for platform in platforms {
        let account = request.accounts.get(&platform).cloned();
        if platform != origin_platform {
            let error = TuneWeaveError::new(
                ErrorCode::MatchRejected,
                "live radio stations are not matched to recordings on another platform",
            )
            .with_platform(platform);
            attempts.push(stream_failed_attempt(platform, account, None, None, &error));
            last_error = Some(error);
            continue;
        }
        let provider = match state.registry.require(platform) {
            Ok(provider) => provider,
            Err(error) => {
                attempts.push(stream_failed_attempt(
                    platform,
                    account,
                    Some(item.source_ref.clone()),
                    Some(1.0),
                    &error,
                ));
                last_error = Some(error);
                continue;
            }
        };
        let station = provider
            .radio_station(item.source_ref.id(), account.as_deref())
            .await;
        match station {
            Ok(station)
                if station
                    .stream_url
                    .as_deref()
                    .is_some_and(|url| !url.is_empty()) =>
            {
                let stream = media_stream_from_radio_station(
                    &item.source_ref,
                    &station,
                    request.quality,
                    account,
                    attempts,
                )?;
                return Ok((
                    stream,
                    Extensions::from([
                        ("transport".to_owned(), json!("live_radio")),
                        ("radio_station".to_owned(), json!(station)),
                    ]),
                ));
            }
            Ok(_) | Err(_) => {}
        }
        let queue = provider
            .radio_playback_queue(
                item.source_ref.id(),
                &RadioPlaybackQueueRequest {
                    limit: 5,
                    account: account.clone(),
                },
            )
            .await;
        match queue {
            Ok(queue) => {
                let playable = queue
                    .items
                    .iter()
                    .find(|entry| {
                        entry
                            .stream_url
                            .as_deref()
                            .is_some_and(|url| !url.is_empty())
                    })
                    .cloned();
                if let Some(playable) = playable {
                    let stream = media_stream_from_radio(
                        &item.source_ref,
                        &playable,
                        request.quality,
                        account,
                        attempts,
                    )?;
                    return Ok((
                        stream,
                        Extensions::from([
                            ("transport".to_owned(), json!("live_radio")),
                            ("playback_item".to_owned(), json!(playable)),
                            ("playback_queue".to_owned(), json!(queue)),
                        ]),
                    ));
                }
                let error = TuneWeaveError::new(
                    ErrorCode::ResourceNotFound,
                    "radio station queue did not expose a playable stream URL",
                )
                .with_platform(platform)
                .with_details(json!({ "queue": queue }));
                attempts.push(stream_failed_attempt(
                    platform,
                    account,
                    Some(item.source_ref.clone()),
                    Some(1.0),
                    &error,
                ));
                last_error = Some(error);
            }
            Err(error) => {
                attempts.push(stream_failed_attempt(
                    platform,
                    account,
                    Some(item.source_ref.clone()),
                    Some(1.0),
                    &error,
                ));
                last_error = Some(error);
            }
        }
    }
    Err(stream_resolution_error(
        item,
        attempts,
        last_error,
        "radio playlist item could not be played",
    ))
}

fn media_stream_from_radio_station(
    source_ref: &ResourceRef,
    station: &RadioStation,
    requested_quality: Quality,
    account: Option<String>,
    mut attempts: Vec<ResolutionAttempt>,
) -> Result<MediaStream, TuneWeaveError> {
    let url = station
        .stream_url
        .clone()
        .filter(|url| !url.is_empty())
        .ok_or_else(|| {
            TuneWeaveError::new(
                ErrorCode::ResourceNotFound,
                "radio station did not expose a stream URL",
            )
            .with_platform(station.platform)
        })?;
    attempts.push(ResolutionAttempt {
        platform: station.platform,
        account,
        candidate: Some(station.resource_ref.clone()),
        match_score: Some(1.0),
        status: ResolutionStatus::Success,
        error: None,
    });
    Ok(MediaStream {
        url,
        backup_urls: Vec::new(),
        headers: BTreeMap::new(),
        expires_at: None,
        format: None,
        codec: None,
        bitrate: None,
        size: None,
        duration_ms: None,
        requested_quality,
        actual_quality: Quality::Auto,
        trial: None,
        origin_track: Some(source_ref.clone()),
        resolved_track: station.resource_ref.clone(),
        resolved_platform: station.platform,
        match_score: Some(1.0),
        attempts,
    })
}

