fn parse_playlist_visibility(
    visibility: Option<&Value>,
    privacy: Option<&Value>,
) -> Result<PlaylistVisibility, TuneWeaveError> {
    let (name, value) = match (visibility, privacy) {
        (Some(_), Some(_)) => {
            return Err(TuneWeaveError::invalid_request(
                "visibility and privacy cannot be provided together",
            )
            .with_details(json!({ "conflicts": ["visibility", "privacy"] })));
        }
        (Some(value), None) => ("visibility", value),
        (None, Some(value)) => ("privacy", value),
        (None, None) => return Ok(PlaylistVisibility::Public),
    };
    let value = required_string_or_number(name, value)?
        .trim()
        .to_ascii_lowercase();
    match value.as_str() {
        "public" | "0" => Ok(PlaylistVisibility::Public),
        "private" | "10" => Ok(PlaylistVisibility::Private),
        _ => Err(TuneWeaveError::invalid_request(format!(
            "{name} must be public, private, 0, or 10"
        ))
        .with_details(json!({ "parameter": name, "value": value }))),
    }
}

fn parse_playlist_kind(
    kind: Option<&Value>,
    playlist_type: Option<&Value>,
) -> Result<PlaylistKind, TuneWeaveError> {
    let (name, value) = match (kind, playlist_type) {
        (Some(_), Some(_)) => {
            return Err(TuneWeaveError::invalid_request(
                "kind and type cannot be provided together",
            )
            .with_details(json!({ "conflicts": ["kind", "type"] })));
        }
        (Some(value), None) => ("kind", value),
        (None, Some(value)) => ("type", value),
        (None, None) => return Ok(PlaylistKind::Normal),
    };
    let value = required_string_or_number(name, value)?
        .trim()
        .to_ascii_lowercase();
    match value.as_str() {
        "normal" | "music" | "track" => Ok(PlaylistKind::Normal),
        "video" | "mv" => Ok(PlaylistKind::Video),
        "shared" => Ok(PlaylistKind::Shared),
        _ => Err(TuneWeaveError::invalid_request(format!(
            "{name} must be normal, video, or shared"
        ))
        .with_details(json!({ "parameter": name, "value": value }))),
    }
}

fn parse_playlist_update_variant(
    value: Option<&str>,
) -> Result<PlaylistMetadataUpdateVariant, TuneWeaveError> {
    match value
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .map(|value| value.to_ascii_lowercase().replace('-', "_"))
        .as_deref()
    {
        None | Some("default") | Some("auto") => Ok(PlaylistMetadataUpdateVariant::Default),
        Some("batch") => Ok(PlaylistMetadataUpdateVariant::Batch),
        Some("individual") | Some("single") => Ok(PlaylistMetadataUpdateVariant::Individual),
        Some(value) => Err(TuneWeaveError::invalid_request(format!(
            "unsupported playlist update variant: {value}"
        ))
        .with_details(json!({ "allowed": ["default", "batch", "individual"] }))),
    }
}

fn parse_playlist_item_kind(
    kind: Option<&Value>,
    item_type: Option<&Value>,
    forced_kind: Option<PlaylistItemKind>,
) -> Result<PlaylistItemKind, TuneWeaveError> {
    let parsed = match (kind, item_type) {
        (Some(_), Some(_)) => {
            return Err(TuneWeaveError::invalid_request(
                "kind and type cannot be provided together",
            )
            .with_details(json!({ "conflicts": ["kind", "type"] })));
        }
        (None, None) => None,
        (Some(value), None) | (None, Some(value)) => {
            let value = required_string_or_number("kind", value)?
                .trim()
                .to_ascii_lowercase();
            Some(match value.as_str() {
                "track" | "song" | "music" | "0" => PlaylistItemKind::Track,
                "video" | "mv" | "3" => PlaylistItemKind::Video,
                _ => {
                    return Err(TuneWeaveError::invalid_request(
                        "playlist item kind must be track or video",
                    )
                    .with_details(json!({ "value": value, "allowed": ["track", "video"] })));
                }
            })
        }
    };
    if let (Some(forced), Some(parsed)) = (forced_kind, parsed)
        && forced != parsed
    {
        return Err(TuneWeaveError::invalid_request(
            "playlist item kind conflicts with the selected endpoint",
        )
        .with_details(json!({ "endpoint_kind": forced, "requested_kind": parsed })));
    }
    Ok(forced_kind.or(parsed).unwrap_or_default())
}

fn parse_playlist_reference_fields(
    refs: Option<PlaylistReferenceInput>,
    ids: Option<PlaylistReferenceInput>,
    platform: Option<&str>,
    default_platform: Platform,
    resource: &str,
) -> Result<Vec<ResourceRef>, TuneWeaveError> {
    match (refs, ids) {
        (Some(_), Some(_)) => Err(TuneWeaveError::invalid_request(
            "refs and ids cannot be provided together",
        )
        .with_details(json!({ "conflicts": ["refs", "ids"] }))),
        (None, None) => Err(TuneWeaveError::invalid_request(
            "one of refs or ids must be provided",
        )),
        (Some(refs), None) => {
            if platform.is_some() {
                return Err(TuneWeaveError::invalid_request(
                    "platform can only be used with ids",
                ));
            }
            split_playlist_reference_values("refs", refs.into_values())?
                .into_iter()
                .map(parse_reference)
                .collect()
        }
        (None, Some(ids)) => {
            let platform = platform.map_or(Ok(default_platform), parse_platform_parameter)?;
            split_playlist_reference_values("ids", ids.into_values())?
                .into_iter()
                .map(|id| {
                    ResourceRef::new(platform, &id).map_err(|error| {
                        TuneWeaveError::invalid_request(format!("invalid {resource} id: {error}"))
                            .with_details(json!({ "id": id, "platform": platform }))
                    })
                })
                .collect()
        }
    }
}

fn split_playlist_reference_values(
    name: &str,
    values: Vec<PlaylistReferenceValue>,
) -> Result<Vec<String>, TuneWeaveError> {
    let mut parsed = Vec::new();
    for value in values {
        let value = value.into_string();
        for item in value.split(',') {
            let item = item.trim();
            if item.is_empty() {
                return Err(TuneWeaveError::invalid_request(format!(
                    "{name} must not contain empty items"
                ))
                .with_details(json!({ "parameter": name })));
            }
            parsed.push(item.to_owned());
        }
    }
    if parsed.is_empty() {
        return Err(TuneWeaveError::invalid_request(format!(
            "{name} must not be empty"
        )));
    }
    Ok(parsed)
}

fn single_reference_platform(
    operation: &str,
    references: &[ResourceRef],
) -> Result<Platform, TuneWeaveError> {
    let Some(platform) = references.first().map(ResourceRef::platform) else {
        return Err(TuneWeaveError::invalid_request(format!(
            "{operation} requires at least one reference"
        )));
    };
    if references
        .iter()
        .any(|reference| reference.platform() != platform)
    {
        return Err(
            TuneWeaveError::invalid_request(format!("{operation} cannot mix platforms"))
                .with_details(json!({ "refs": references })),
        );
    }
    Ok(platform)
}

async fn playlist(
    State(state): State<AppState>,
    headers: HeaderMap,
    Path(reference): Path<String>,
    Query(params): Query<AccountParams>,
) -> Result<Json<ApiResponse<Playlist>>, ApiError> {
    let credentials = CallerCredentialSet::from_headers(&headers, &state)?;
    let reference = parse_reference(reference)?;
    let platform = reference.platform();
    if platform == Platform::Uni {
        if params.account.is_some() {
            return Err(TuneWeaveError::invalid_request(
                "local Uni Playlists do not use platform accounts",
            )
            .into());
        }
        let playlist = state.uni_playlists.get(reference.id())?.ok_or_else(|| {
            TuneWeaveError::new(ErrorCode::ResourceNotFound, "Uni Playlist was not found")
                .with_details(json!({ "ref": reference }))
        })?;
        return Ok(Json(
            ApiResponse::new(playlist_from_uni(playlist)).with_platform(Platform::Uni),
        ));
    }
    let access = credentials.select_provider(
        &state,
        platform,
        params.account.as_deref(),
        AccountSelection::Optional,
    )?;
    let playlist = access
        .provider
        .playlist(reference.id(), access.provider_account.as_deref())
        .await?;
    let mut response = ApiResponse::new(playlist).with_platform(platform);
    if let Some(account) = access.response_account {
        response = response.with_account(account);
    }

    Ok(Json(response))
}

#[derive(Debug, Default, Deserialize)]
struct PageParams {
    limit: Option<String>,
    offset: Option<String>,
    account: Option<String>,
}

async fn playlist_tracks(
    State(state): State<AppState>,
    headers: HeaderMap,
    Path(reference): Path<String>,
    Query(params): Query<PageParams>,
) -> Result<Json<ApiResponse<Vec<Track>>>, ApiError> {
    let credentials = CallerCredentialSet::from_headers(&headers, &state)?;
    let reference = parse_reference(reference)?;
    let limit = parse_u32_parameter("limit", params.limit.as_deref(), 30)?;
    if !(1..=100).contains(&limit) {
        return Err(TuneWeaveError::invalid_request("limit must be between 1 and 100").into());
    }
    let offset = parse_u32_parameter("offset", params.offset.as_deref(), 0)?;
    let platform = reference.platform();
    if platform == Platform::Uni {
        if params.account.is_some() {
            return Err(TuneWeaveError::invalid_request(
                "local Uni Playlists do not use platform accounts",
            )
            .into());
        }
        let tracks = all_uni_playlist_items(&state, reference.id())?
            .into_iter()
            .filter(|item| item.kind == UniPlaylistItemKind::Track)
            .map(track_from_uni_item)
            .collect::<Vec<_>>();
        let total = u64::try_from(tracks.len()).unwrap_or(u64::MAX);
        let items = tracks
            .into_iter()
            .skip(offset as usize)
            .take(limit as usize)
            .collect::<Vec<_>>();
        let consumed = u32::try_from(items.len()).unwrap_or(u32::MAX);
        let next = offset.saturating_add(consumed);
        let has_more = u64::from(next) < total;
        return Ok(Json(
            ApiResponse::new(items)
                .with_platform(Platform::Uni)
                .with_pagination(PageMeta {
                    limit,
                    offset,
                    total: Some(total),
                    next_offset: has_more.then_some(next),
                    has_more,
                    extensions: Extensions::from([
                        ("mixed_items_filtered".to_owned(), json!(true)),
                        ("item_kind".to_owned(), json!("track")),
                    ]),
                }),
        ));
    }
    let access = credentials.select_provider(
        &state,
        platform,
        params.account.as_deref(),
        AccountSelection::Optional,
    )?;
    let page = access
        .provider
        .playlist_tracks(
            reference.id(),
            &PageRequest {
                limit,
                offset,
                account: access.provider_account,
            },
        )
        .await?;
    let mut response = ApiResponse::new(page.items)
        .with_platform(platform)
        .with_pagination(page.pagination);
    if let Some(account) = access.response_account {
        response = response.with_account(account);
    }

    Ok(Json(response))
}

async fn playlist_playable_items(
    State(state): State<AppState>,
    headers: HeaderMap,
    Path(reference): Path<String>,
    Query(params): Query<PageParams>,
) -> Result<Json<ApiResponse<Vec<PlaylistPlayableEntry>>>, ApiError> {
    let credentials = CallerCredentialSet::from_headers(&headers, &state)?;
    let reference = parse_reference(reference)?;
    let limit = parse_u32_parameter("limit", params.limit.as_deref(), 30)?;
    if !(1..=100).contains(&limit) {
        return Err(TuneWeaveError::invalid_request("limit must be between 1 and 100").into());
    }
    let offset = parse_u32_parameter("offset", params.offset.as_deref(), 0)?;
    let platform = reference.platform();
    if platform == Platform::Uni {
        if params.account.is_some() {
            return Err(TuneWeaveError::invalid_request(
                "local Uni Playlists do not use platform accounts",
            )
            .into());
        }
        let page = state.uni_playlists.items(reference.id(), limit, offset)?;
        let items = page
            .items
            .into_iter()
            .map(playlist_playable_entry_from_uni)
            .collect();
        return Ok(Json(
            ApiResponse::new(items)
                .with_platform(Platform::Uni)
                .with_pagination(page.pagination),
        ));
    }
    let access = credentials.select_provider(
        &state,
        platform,
        params.account.as_deref(),
        AccountSelection::Optional,
    )?;
    let page = access
        .provider
        .playlist_source_items(
            reference.id(),
            "playlist",
            &PageRequest {
                limit,
                offset,
                account: access.provider_account,
            },
        )
        .await?;
    let items = page
        .items
        .into_iter()
        .enumerate()
        .map(|(index, item)| {
            playlist_playable_entry_from_provider(
                item,
                u64::from(offset).saturating_add(u64::try_from(index).unwrap_or(u64::MAX)),
            )
        })
        .collect();
    let mut response = ApiResponse::new(items)
        .with_platform(platform)
        .with_pagination(page.pagination);
    if let Some(account) = access.response_account {
        response = response.with_account(account);
    }
    Ok(Json(response))
}

fn playlist_from_uni(playlist: UniPlaylist) -> Playlist {
    let mut extensions = playlist.extensions;
    extensions.insert("uni_item_count".to_owned(), json!(playlist.item_count));
    extensions.insert("created_at_ms".to_owned(), json!(playlist.created_at_ms));
    extensions.insert("updated_at_ms".to_owned(), json!(playlist.updated_at_ms));
    extensions.insert("mixed_playable_items".to_owned(), json!(true));
    Playlist {
        resource_ref: playlist.resource_ref,
        platform: Platform::Uni,
        id: playlist.id,
        name: playlist.name,
        description: playlist.description,
        cover_url: None,
        creator: None,
        track_count: None,
        tags: Vec::new(),
        subscribed: None,
        created_at: None,
        updated_at: None,
        extensions,
    }
}

fn all_uni_playlist_items(
    state: &AppState,
    playlist_id: &str,
) -> Result<Vec<UniPlaylistItem>, TuneWeaveError> {
    let mut offset = 0;
    let mut items = Vec::new();
    loop {
        let page = state.uni_playlists.items(playlist_id, 100, offset)?;
        items.extend(page.items);
        if !page.pagination.has_more {
            return Ok(items);
        }
        offset = page.pagination.next_offset.ok_or_else(|| {
            TuneWeaveError::new(
                ErrorCode::InternalError,
                "local Uni Playlist pagination did not provide next_offset",
            )
        })?;
    }
}

fn playlist_playable_entry_from_uni(item: UniPlaylistItem) -> PlaylistPlayableEntry {
    let mut extensions = item.extensions;
    extensions.insert("stable_item_id".to_owned(), json!(true));
    PlaylistPlayableEntry {
        item_id: Some(item.id),
        position: item.position,
        kind: item.kind,
        resource_ref: item.source_ref,
        snapshot: item.snapshot,
        extensions,
    }
}

fn playlist_playable_entry_from_provider(
    item: PlaylistPlayableItem,
    position: u64,
) -> PlaylistPlayableEntry {
    let imported = playlist_playable_to_uni_imported_item(item);
    let mut extensions = imported.extensions;
    extensions.insert("stable_item_id".to_owned(), json!(false));
    PlaylistPlayableEntry {
        item_id: None,
        position,
        kind: imported.kind,
        resource_ref: imported.source_ref,
        snapshot: imported.snapshot,
        extensions,
    }
}

fn track_from_uni_item(item: UniPlaylistItem) -> Track {
    let snapshot = item.snapshot;
    let mut extensions = snapshot.extensions;
    let playable = extensions.get("playable").and_then(Value::as_bool);
    let available_qualities = extensions
        .get("available_qualities")
        .cloned()
        .and_then(|value| serde_json::from_value(value).ok())
        .unwrap_or_default();
    let mv_ref = extensions
        .get("mv_ref")
        .cloned()
        .and_then(|value| serde_json::from_value(value).ok());
    extensions.insert("uni_item_id".to_owned(), json!(item.id));
    extensions.insert("uni_position".to_owned(), json!(item.position));
    let mut track = Track::new(item.source_ref, snapshot.title);
    track.aliases = snapshot.version_tags;
    track.artists = snapshot
        .artists
        .into_iter()
        .map(|name| ArtistSummary {
            resource_ref: None,
            name,
        })
        .collect();
    track.album = snapshot.album.map(|name| AlbumSummary {
        resource_ref: None,
        name,
        cover_url: snapshot.cover_url,
    });
    track.duration_ms = snapshot.duration_ms;
    track.isrc = snapshot.isrc;
    track.mv_ref = mv_ref;
    track.playable = playable;
    track.available_qualities = available_qualities;
    track.extensions = extensions;
    track
}

