    let account = optional_trimmed(body.account);
    let protocol = optional_trimmed(body.crypto);
    let access = CallerCredentialSet::from_headers(&headers, &state)?.select_provider(
        &state,
        Platform::Netease,
        account.as_deref(),
        AccountSelection::Optional,
    )?;
