fn parse_digital_album_chart_period(
    value: Option<&str>,
) -> Result<DigitalAlbumChartPeriod, TuneWeaveError> {
    match value
        .unwrap_or("daily")
        .trim()
        .to_ascii_lowercase()
        .as_str()
    {
        "daily" => Ok(DigitalAlbumChartPeriod::Daily),
        "week" => Ok(DigitalAlbumChartPeriod::Week),
        "year" => Ok(DigitalAlbumChartPeriod::Year),
        "total" => Ok(DigitalAlbumChartPeriod::Total),
        value => Err(TuneWeaveError::invalid_request(format!(
            "unsupported digital album chart period: {value}"
        ))
        .with_details(json!({ "allowed": ["daily", "week", "year", "total"] }))),
    }
}

fn parse_digital_album_chart_kind(
    value: Option<&str>,
) -> Result<DigitalAlbumChartKind, TuneWeaveError> {
    match value
        .unwrap_or("album")
        .trim()
        .to_ascii_lowercase()
        .as_str()
    {
        "album" => Ok(DigitalAlbumChartKind::Album),
        "single" => Ok(DigitalAlbumChartKind::Single),
        value => Err(TuneWeaveError::invalid_request(format!(
            "unsupported digital album chart type: {value}"
        ))
        .with_details(json!({ "allowed": ["album", "single"] }))),
    }
}

fn parse_bool_parameter(
    name: &str,
    value: Option<&str>,
    default: bool,
) -> Result<bool, TuneWeaveError> {
    match value.map(str::trim).map(str::to_ascii_lowercase) {
        None => Ok(default),
        Some(value) if value == "true" || value == "1" => Ok(true),
        Some(value) if value == "false" || value == "0" => Ok(false),
        Some(value) => Err(TuneWeaveError::invalid_request(format!(
            "{name} must be true or false"
        ))
        .with_details(json!({ "parameter": name, "value": value }))),
    }
}

fn parse_platform_parameter(value: &str) -> Result<Platform, TuneWeaveError> {
    let value = value.trim();
    value
        .parse()
        .map_err(|_| TuneWeaveError::invalid_request(format!("unsupported platform: {value}")))
}

fn parse_platform_list(value: Option<&str>) -> Result<Vec<Platform>, TuneWeaveError> {
    value.map_or_else(
        || Ok(Vec::new()),
        |value| {
            value
                .split(',')
                .map(str::trim)
                .filter(|platform| !platform.is_empty())
                .map(parse_platform_parameter)
                .collect()
        },
    )
}

fn search_platform(state: &AppState, value: Option<&str>) -> Result<Platform, TuneWeaveError> {
    let Some(value) = value.map(str::trim).filter(|value| !value.is_empty()) else {
        return Ok(state.default_platform);
    };
    if value.eq_ignore_ascii_case("all") {
        let registered = state.registry.descriptors();
        return match registered.as_slice() {
            [provider] => Ok(provider.platform),
            [] => Err(TuneWeaveError::platform_unavailable(state.default_platform)),
            _ => Err(TuneWeaveError::invalid_request(
                "platform=all is not available until aggregate ranking is enabled",
            )),
        };
    }
    value
        .parse()
        .map_err(|_| TuneWeaveError::invalid_request(format!("unsupported platform: {value}")))
}

fn parse_search_kind(value: Option<&str>) -> Result<SearchKind, TuneWeaveError> {
    match value
        .unwrap_or("track")
        .trim()
        .to_ascii_lowercase()
        .as_str()
    {
        "track" | "song" | "1" => Ok(SearchKind::Track),
        "album" | "10" => Ok(SearchKind::Album),
        "artist" | "100" => Ok(SearchKind::Artist),
        "playlist" | "1000" => Ok(SearchKind::Playlist),
        "user" | "1002" => Ok(SearchKind::User),
        "mv" | "1004" => Ok(SearchKind::Mv),
        "lyric" | "lyrics" | "1006" => Ok(SearchKind::Lyric),
        "radio_station" | "radio" | "broadcast" => Ok(SearchKind::RadioStation),
        "podcast" | "podcasts" | "dj" | "dj_radio" | "1009" => Ok(SearchKind::Podcast),
        "video" | "1014" => Ok(SearchKind::Video),
        "mixed" | "complex" | "1018" => Ok(SearchKind::Mixed),
        "voice" | "2000" => Ok(SearchKind::Voice),
        "ringtone" | "ring" => Ok(SearchKind::Ringtone),
        value => Err(
            TuneWeaveError::invalid_request(format!("unsupported search type: {value}"))
                .with_details(json!({
                    "allowed": [
                        "track", "album", "artist", "playlist", "user", "mv", "lyric",
                        "radio_station", "podcast", "video", "mixed", "voice", "ringtone",
                        1, 10, 100, 1000, 1002, 1004, 1006, 1009, 1014, 1018, 2000
                    ]
                })),
        ),
    }
}

fn parse_search_selectors(value: Option<&str>) -> Result<Vec<SearchSelector>, TuneWeaveError> {
    let Some(value) = value.map(str::trim).filter(|value| !value.is_empty()) else {
        return Ok(Vec::new());
    };
    let inputs = serde_json::from_str::<Vec<SearchSelectorInput>>(value).map_err(|error| {
        TuneWeaveError::invalid_request("selectors must be a JSON array of {id,name,type}")
            .with_details(json!({ "error": error.to_string() }))
    })?;
    let mut types = BTreeSet::new();
    inputs
        .into_iter()
        .map(|input| {
            if !types.insert(input.selector_type) {
                return Err(TuneWeaveError::invalid_request(
                    "search selectors must use unique types",
                )
                .with_details(json!({ "type": input.selector_type })));
            }
            Ok(SearchSelector {
                id: input.id,
                name: input.name,
                selector_type: input.selector_type,
                extensions: Extensions::new(),
            })
        })
        .collect()
}

fn parse_video_search_filters(
    kind: SearchKind,
    order: Option<&str>,
    duration: Option<&str>,
    category_id: Option<&str>,
) -> Result<Option<VideoSearchFilters>, TuneWeaveError> {
    if order.is_none() && duration.is_none() && category_id.is_none() {
        return Ok(None);
    }
    if kind != SearchKind::Video {
        return Err(TuneWeaveError::invalid_request(
            "order, duration, and category_id are only valid for video search",
        ));
    }
    let order = match order
        .unwrap_or("relevance")
        .trim()
        .to_ascii_lowercase()
        .replace('-', "_")
        .as_str()
    {
        "relevance" | "default" | "totalrank" => VideoSearchOrder::Relevance,
        "most_played" | "play" | "click" => VideoSearchOrder::MostPlayed,
        "newest" | "latest" | "pubdate" => VideoSearchOrder::Newest,
        "most_danmaku" | "danmaku" | "dm" => VideoSearchOrder::MostDanmaku,
        "most_favorited" | "most_favourite" | "favorite" | "favourite" | "stow" => {
            VideoSearchOrder::MostFavorited
        }
        "most_commented" | "comments" | "scores" => VideoSearchOrder::MostCommented,
        value => {
            return Err(TuneWeaveError::invalid_request(format!(
                "unsupported video search order: {value}"
            ))
            .with_details(json!({
                "allowed": [
                    "relevance",
                    "most_played",
                    "newest",
                    "most_danmaku",
                    "most_favorited",
                    "most_commented"
                ]
            })));
        }
    };
    let duration = match duration
        .unwrap_or("any")
        .trim()
        .to_ascii_lowercase()
        .replace(['-', ' '], "_")
        .as_str()
    {
        "any" | "all" | "0" => VideoSearchDuration::Any,
        "under_ten_minutes" | "under_10_minutes" | "under_10m" | "1" => {
            VideoSearchDuration::UnderTenMinutes
        }
        "ten_to_thirty_minutes" | "10_to_30_minutes" | "10_30m" | "2" => {
            VideoSearchDuration::TenToThirtyMinutes
        }
        "thirty_to_sixty_minutes" | "30_to_60_minutes" | "30_60m" | "3" => {
            VideoSearchDuration::ThirtyToSixtyMinutes
        }
        "over_sixty_minutes" | "over_60_minutes" | "over_60m" | "4" => {
            VideoSearchDuration::OverSixtyMinutes
        }
        value => {
            return Err(TuneWeaveError::invalid_request(format!(
                "unsupported video search duration: {value}"
            ))
            .with_details(json!({
                "allowed": [
                    "any",
                    "under_ten_minutes",
                    "ten_to_thirty_minutes",
                    "thirty_to_sixty_minutes",
                    "over_sixty_minutes"
                ]
            })));
        }
    };
    let category_id = category_id
        .map(str::trim)
        .filter(|value| !value.is_empty() && *value != "0")
        .map(|value| {
            value
                .parse::<u32>()
                .ok()
                .filter(|value| *value > 0)
                .map_or_else(
                    || {
                        Err(TuneWeaveError::invalid_request(
                            "video search category_id must be a positive integer",
                        ))
                    },
                    |value| Ok(value.to_string()),
                )
        })
        .transpose()?;
    Ok(Some(VideoSearchFilters {
        order,
        duration,
        category_id,
    }))
}

