fn unix_time_millis() -> Result<u64, TuneWeaveError> {
    let duration = SystemTime::now().duration_since(UNIX_EPOCH).map_err(|_| {
        TuneWeaveError::new(
            tuneweave_core::ErrorCode::InternalError,
            "system clock is before the Unix epoch",
        )
    })?;
    u64::try_from(duration.as_millis()).map_err(|_| {
        TuneWeaveError::new(
            tuneweave_core::ErrorCode::InternalError,
            "system time exceeds the supported millisecond range",
        )
    })
}

fn unix_time_seconds() -> Result<u64, TuneWeaveError> {
    SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .map(|duration| duration.as_secs())
        .map_err(|_| {
            TuneWeaveError::new(
                tuneweave_core::ErrorCode::InternalError,
                "system clock is before the Unix epoch",
            )
        })
}

fn unix_epoch_seconds_rfc3339(timestamp: u64) -> Option<String> {
    let days = i64::try_from(timestamp / 86_400).ok()?;
    let seconds = timestamp % 86_400;
    let z = days.checked_add(719_468)?;
    let era = if z >= 0 { z } else { z - 146_096 } / 146_097;
    let day_of_era = z - era * 146_097;
    let year_of_era =
        (day_of_era - day_of_era / 1_460 + day_of_era / 36_524 - day_of_era / 146_096) / 365;
    let mut year = year_of_era + era * 400;
    let day_of_year = day_of_era - (365 * year_of_era + year_of_era / 4 - year_of_era / 100);
    let month_prime = (5 * day_of_year + 2) / 153;
    let day = day_of_year - (153 * month_prime + 2) / 5 + 1;
    let month = month_prime + if month_prime < 10 { 3 } else { -9 };
    if month <= 2 {
        year += 1;
    }
    if !(0..=9_999).contains(&year) {
        return None;
    }
    let hour = seconds / 3_600;
    let minute = (seconds % 3_600) / 60;
    let second = seconds % 60;
    Some(format!(
        "{year:04}-{month:02}-{day:02}T{hour:02}:{minute:02}:{second:02}Z"
    ))
}

