    fn test_app_with_bilibili_uni_items() -> Router {
        let mut registry = ProviderRegistry::new();
        registry
            .register(TestBilibiliProvider)
            .expect("register Bilibili provider");
        registry
            .register(TestQqProvider)
            .expect("register QQ provider");

        let store = Arc::new(MemoryUniPlaylistStore::default());
        let playlist_ref = ResourceRef::new(Platform::Uni, "pl_bilibili_audio")
            .expect("valid Uni Playlist reference");
        let mut playlist = UniPlaylist::new(
            playlist_ref,
            "B 站音频与回退",
            "验证原始音轨优先和严格匹配回退",
            1_753_137_600_000,
        );
        playlist.item_count = 2;
        playlist.updated_at_ms = 1_753_137_600_200;
        let item = |id: &str, source_id: &str, position: u64| {
            let mut snapshot = UniPlaylistItemSnapshot::new("任性 (5525 Live版)");
            snapshot.artists = vec!["周杰伦".to_owned()];
            snapshot.duration_ms = Some(266_000);
            snapshot
                .extensions
                .insert("playable".to_owned(), json!(true));
            UniPlaylistItem {
                id: id.to_owned(),
                position,
                kind: UniPlaylistItemKind::Video,
                source_ref: ResourceRef::new(Platform::Bilibili, source_id)
                    .expect("valid Bilibili source reference"),
                snapshot,
                added_at_ms: 1_753_137_600_100 + position,
                extensions: Extensions::new(),
            }
        };
        store
            .create_with_items(
                &playlist,
                &[
                    item("item_bili_native", "bvid:native", 0),
                    item("item_bili_fallback", "bvid:fallback", 1),
                ],
            )
            .expect("create Bilibili Uni Playlist");
        build_router(AppState::new(registry, Platform::Bilibili).with_uni_playlist_store(store))
    }

    async fn json_response_from(app: Router, path: &str) -> (StatusCode, Value) {
        json_request_from(app, Method::GET, path, None).await
    }

    async fn json_request_from(
        app: Router,
        method: Method,
        path: &str,
        json_body: Option<Value>,
    ) -> (StatusCode, Value) {
        let (status, _, json) = json_request_with_headers(app, method, path, json_body).await;
        (status, json)
    }

    async fn json_request_with_headers(
        app: Router,
        method: Method,
        path: &str,
        json_body: Option<Value>,
    ) -> (StatusCode, HeaderMap, Value) {
        let mut request = Request::builder().method(method).uri(path);
        let body = if let Some(json_body) = json_body {
            request = request.header(header::CONTENT_TYPE, "application/json");
            Body::from(serde_json::to_vec(&json_body).expect("serialize request JSON"))
        } else {
            Body::empty()
        };
        let response = app
            .oneshot(request.body(body).expect("build request"))
            .await
            .expect("request succeeds");
        let status = response.status();
        let headers = response.headers().clone();
        let body = to_bytes(response.into_body(), usize::MAX)
            .await
            .expect("read body");
        let json = serde_json::from_slice(&body).expect("valid JSON");
        (status, headers, json)
    }

    async fn caller_json_request(
        app: Router,
        method: Method,
        path: &str,
        json_body: Option<Value>,
        credential: &CallerCredential,
    ) -> (StatusCode, Value) {
        let mut request = Request::builder()
            .method(method)
            .uri(path)
            .header(CALLER_CREDENTIAL_HEADER, credential.value.clone());
        let body = if let Some(json_body) = json_body {
            request = request.header(header::CONTENT_TYPE, "application/json");
            Body::from(serde_json::to_vec(&json_body).expect("serialize request JSON"))
        } else {
            Body::empty()
        };
        let response = app
            .oneshot(request.body(body).expect("build caller request"))
            .await
            .expect("caller request succeeds");
        let status = response.status();
        let body = to_bytes(response.into_body(), usize::MAX)
            .await
            .expect("read caller response body");
        let json = serde_json::from_slice(&body).expect("valid caller response JSON");
        (status, json)
    }

    async fn binary_request_from(
        app: Router,
        path: &str,
        content_type: Option<&str>,
        body: Vec<u8>,
    ) -> (StatusCode, Value) {
        binary_request_with_method(app, Method::PUT, path, content_type, body).await
    }

    async fn binary_request_with_method(
        app: Router,
        method: Method,
        path: &str,
        content_type: Option<&str>,
        body: Vec<u8>,
    ) -> (StatusCode, Value) {
        let mut request = Request::builder().method(method).uri(path);
        if let Some(content_type) = content_type {
            request = request.header(header::CONTENT_TYPE, content_type);
        }
        let response = app
            .oneshot(request.body(Body::from(body)).expect("build request"))
            .await
            .expect("request succeeds");
        let status = response.status();
        let body = to_bytes(response.into_body(), usize::MAX)
            .await
            .expect("read body");
        let json = serde_json::from_slice(&body).expect("valid JSON");
        (status, json)
    }

    async fn caller_binary_request(
        app: Router,
        method: Method,
        path: &str,
        content_type: &str,
        body: Vec<u8>,
        credential: &CallerCredential,
    ) -> (StatusCode, Value) {
        let response = app
            .oneshot(
                Request::builder()
                    .method(method)
                    .uri(path)
                    .header(header::CONTENT_TYPE, content_type)
                    .header(CALLER_CREDENTIAL_HEADER, credential.value.clone())
                    .body(Body::from(body))
                    .expect("build caller binary request"),
            )
            .await
            .expect("caller binary request succeeds");
        let status = response.status();
        let body = to_bytes(response.into_body(), usize::MAX)
            .await
            .expect("read caller binary response body");
        let json = serde_json::from_slice(&body).expect("valid caller binary response JSON");
        (status, json)
    }

